jQuery(function($) {
    const versionInfoHandler = {
        init() {
            // Attach click event to the "Show Version Info" admin bar link
            $("#wp-admin-bar-show-version-info").on("click", this.showModal);
        },

        showModal(event) {
            event.preventDefault();

            // Check if the modal already exists
            if ($(".wc-backbone-modal-beta-tester-version-info").length > 0) {
                return;
            }

            // Create and show the modal using WCBackboneModal
            $(this).WCBackboneModal({
                template: "wc-beta-tester-version-info",
                variable: {
                    version: wc_beta_tester_version_info_params.version,
                    description: wc_beta_tester_version_info_params.description,
                },
            });
        },
    };

    versionInfoHandler.init();
});
